insert into `portfolio` (`categorie`, `client`, `date_creation`, `date_realisation`, `description`, `id`, `image_url`, `ordre_affichage`, `technologies`, `titre`, `url_projet`, `visible`) values ('site_web', NULL, '2026-01-24 15:46:55', NULL, 'Yummy Nouilles redéfinit l\'expérience du ramen en France à travers une immersion culinaire totale. Présente dans plusieurs grandes villes, cette enseigne propose une cuisine japonaise traditionnelle exécutée avec passion par des chefs venus directement du Japon. Chaque bol raconte une histoire de savoir-faire ancestral, où les bouillons mijotés de longues heures et les nouilles fraîches rencontrent un concept original et moderne. L\'architecture digitale que nous avons conçue pour eux reflète cette alliance entre tradition nippone et dynamisme urbain. Un projet sur-mesure pour une chaîne de restaurants qui place l\'authenticité et l\'excellence au cœur de son développement national.', 1, 'yummy-nouille.png', 0, NULL, 'Yummy Nouille', NULL, 1);
