insert into `portfolio` (`categorie`, `client`, `date_creation`, `date_realisation`, `description`, `id`, `image_url`, `ordre_affichage`, `technologies`, `titre`, `url_projet`, `visible`) values ('site_web', NULL, '2026-01-24 15:46:55', NULL, 'Plongez dans l\'univers dynamique de Subway à travers une plateforme web haute en couleurs, conçue pour refléter la fraîcheur et la diversité de leurs célèbres sandwichs. Ce site au design audacieux et original propose une expérience interactive unique : un configurateur de menus sur mesure. Les utilisateurs peuvent composer leur sandwich idéal ingrédient par ingrédient, créant ainsi un repas totalement personnalisé selon leurs envies du moment. Pour les plus aventureux, nous avons intégré une fonctionnalité exclusive de sélection aléatoire, ajoutant une touche de fun et de surprise à la commande. Un projet digital innovant qui transforme la personnalisation alimentaire en un véritable jeu visuel et gastronomique.', 3, 'subway.png', 0, NULL, 'Subway', NULL, 1);
