insert into `portfolio` (`categorie`, `client`, `date_creation`, `date_realisation`, `description`, `id`, `image_url`, `ordre_affichage`, `technologies`, `titre`, `url_projet`, `visible`) values ('site_web', NULL, '2026-01-24 15:46:55', NULL, 'SOIF 200 est une plateforme digitale immersive conçue exclusivement pour une clientèle surnaturelle, allant des vampires aux loups-garous. Sous le slogan évocateur \'Une vie éternellement confortable\', le site propose une gamme de services premium adaptés aux besoins des êtres éthérés : gestion de cryptes, soins esthétiques pour immortels et organisation d\'événements nocturnes raffinés. L\'interface, aux teintes pourpres et sombres, reflète une esthétique gothique moderne tout en offrant une navigation fluide et élégante. Avec une tarification claire pour des prestations de luxe et une section de contact directe, SOIF 200 s\'impose comme la référence absolue pour ceux qui vivent en dehors des heures solaires.', 5, 'soif200.png', 0, NULL, 'Soif200', NULL, 1);
