insert into `portfolio` (`categorie`, `client`, `date_creation`, `date_realisation`, `description`, `id`, `image_url`, `ordre_affichage`, `technologies`, `titre`, `url_projet`, `visible`) values ('site_web', NULL, '2026-01-24 15:46:55', NULL, 'SnapFace est un réseau social à taille humaine, conçu pour remettre l\'essentiel au cœur des échanges numériques. Loin de la complexité des plateformes traditionnelles, il propose une interface épurée et intuitive, pensée spécifiquement pour les familles et les personnes moins à l\'aise avec la technologie. L\'objectif est simple : permettre à chacun de partager des moments de vie, des photos et des souvenirs en quelques clics seulement. Grâce à son design \'simple mais efficace\', SnapFace devient le pont idéal pour garder un contact précieux avec ses proches et ses amis, garantissant une expérience fluide où la technologie s\'efface au profit du lien social. Une solution rassurante pour ne plus jamais perdre le fil avec ceux qui comptent vraiment.', 7, 'snapface.png', 0, NULL, 'Snapface', NULL, 1);
