insert into `portfolio` (`categorie`, `client`, `date_creation`, `date_realisation`, `description`, `id`, `image_url`, `ordre_affichage`, `technologies`, `titre`, `url_projet`, `visible`) values ('site_web', NULL, '2026-01-24 15:46:55', NULL, 'La plateforme Bibliothèque a été conçue comme l\'outil de gestion ultime pour les bibliophiles passionnés. Elle permet de répertorier, trier et filtrer ses ouvrages par auteur ou par genre littéraire en un clin d\'œil. Pensée pour ceux qui aiment aller à l\'essentiel, son interface épurée facilite l\'organisation d\'une collection personnelle, garantissant aux lecteurs de toujours savoir quel sera leur prochain livre. C\'est la solution idéale pour garder une vue d\'ensemble sur sa pile à lire et ne jamais se retrouver à court d\'inspiration. Un véritable assistant numérique qui transforme la gestion d\'une bibliothèque en une expérience fluide et gratifiante.', 9, 'bibliotheque.png', 0, NULL, 'Bibliothèque', NULL, 1);
