insert into `portfolio` (`categorie`, `client`, `date_creation`, `date_realisation`, `description`, `id`, `image_url`, `ordre_affichage`, `technologies`, `titre`, `url_projet`, `visible`) values ('site_web', NULL, '2026-01-24 15:46:55', NULL, 'LuxeList est une plateforme de gestion de tâches haut de gamme, conçue par des professionnels pour des professionnels exigeants. Alliant une esthétique minimaliste à une efficacité redoutable, cet outil permet de structurer vos flux de travail en catégorisant vos actions : à faire, terminées ou en cours. La force de LuxeList réside dans son compteur dynamique intégré, qui offre une vision en temps réel de l\'avancement de vos projets. C’est le compagnon idéal pour ne jamais perdre le fil au cœur d\'une production complexe et garantir une organisation sans faille. Une interface élégante au service d\'une productivité maximale, pour ceux qui ne laissent aucune place au hasard.', 11, 'luxeList.png', 0, NULL, 'LuxeList', NULL, 1);
